    "css": "button {\n  position: relative;\n  padding: 13px 35px;\n  background: #f5ddb7;\n  font-size: 17px;\n  font-weight: 900;\n  color: #181818;\n  border: none;\n  border-radius: 8px;\n  box-shadow: 2px 2px 5px #18181869, inset 2px 2px 10px #ffffffb0;\n  transition: all .3s ease-in-out;\n}\n\n.icon-1 {\n  position: absolute;\n  top: 10%;\n  left: 50%;\n  transform: translate(-50%, 0);\n  width: 0px;\n  height: auto;\n  transition: all .5s ease-in-out;\n  z-index: -1;\n}\n\n.icon-2 {\n  position: absolute;\n  top: 10%;\n  left: 50%;\n  transform: translate(-50%, 0);\n  width: 0px;\n  height: auto;\n  transition: all .5s ease-in-out;\n  z-index: -2;\n}\n\n.icon-3 {\n  position: absolute;\n  top: 10%;\n  left: 50%;\n  transform: translate(-50%, 0);\n  width: 0px;\n  height: auto;\n  transition: all .5s ease-in-out;\n  z-index: -2;\n}\n\n.icon-4 {\n  position: absolute;\n  top: 10%;\n  left: 50%;\n  transform: translate(-50%, 0);\n  width: 0px;\n  height: auto;\n  transition: all .5s ease-in-out;\n  z-index: -2;\n}\n\n.icon-5 {\n  position: absolute;\n  top: 10%;\n  left: 50%;\n  transform: translate(-50%, 0);\n  width: 0px;\n  height: auto;\n  transition: all .5s ease-in-out;\n  z-index: -2;\n}\n\nbutton:hover {\n  padding: 13px 25px;\n  border-radius: 8px 8px 24px 24px;\n}\n\nbutton:hover .icon-1 {\n  top: -250%;\n  left: 50%;\n  transform: translate(-50%, 0);\n  width: 50px;\n  height: auto;\n  animation: inIcon1 1s ease .45s forwards;\n}\n\n@keyframes inIcon1 {\n  0% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n\n  25% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(5deg);\n  }\n\n  50% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(1deg);\n  }\n\n  65% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(3deg);\n  }\n\n  100% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n}\n\nbutton:hover .icon-2 {\n  position: absolute;\n  top: -200%;\n  left: 90%;\n  transform: translate(-50%, 0);\n  width: 75px;\n  height: auto;\n  animation: inIcon2 1s ease .45s forwards;\n}\n\n@keyframes inIcon2 {\n  0% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n\n  35% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(10deg);\n  }\n\n  50% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(4deg);\n  }\n\n  80% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(5deg);\n  }\n\n  100% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n}\n\nbutton:hover .icon-3 {\n  position: absolute;\n  top: -130%;\n  left: 20%;\n  transform: translate(-50%, 0);\n  width: 60px;\n  height: auto;\n  animation: inIcon3 1s ease .45s forwards;\n}\n\n@keyframes inIcon3 {\n  0% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n\n  35% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(-2deg);\n  }\n\n  100% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n}\n\nbutton:hover .icon-4 {\n  position: absolute;\n  top: -300%;\n  left: 10%;\n  transform: translate(-50%, 0);\n  width: 85px;\n  height: auto;\n  animation: inIcon4 1s ease .45s forwards;\n}\n\n@keyframes inIcon4 {\n  0% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n\n  40% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(-3deg);\n  }\n\n  100% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n}\n\nbutton:hover .icon-5 {\n  position: absolute;\n  top: -350%;\n  left: 90%;\n  transform: translate(-50%, 0);\n  width: 85px;\n  height: auto;\n  animation: inIcon5 1s ease .45s forwards;\n}\n\n@keyframes inIcon5 {\n  0% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n\n  35% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(-3deg);\n  }\n\n  100% {\n    transform-origin: 0 100%;\n    transform: translate(-50%, 0) rotate(0deg);\n  }\n}\n\n.fil-leaf-1 {\n  fill: #7B9B3A\n}\n\n.fil-leaf-2 {\n  fill: #556729;\n  fill-rule: nonzero\n}\n\n.fil-leaf-3 {\n  fill: #556729\n}\n\n.fil-leaf-4 {\n  fill: #3C4819\n}\n\n.fil-leaf-5 {\n  fill: #3C4819\n}"
