    "html": "<label class=\"label\">\n  <span class=\"icon\">\n    <svg\n      class=\"w-6 h-6 text-gray-800 dark:text-white\"\n      aria-hidden=\"true\"\n      xmlns=\"http://www.w3.org/2000/svg\"\n      width=\"30\"\n      height=\"30\"\n      fill=\"none\"\n      viewBox=\"0 0 24 24\"\n    >\n      <path\n        stroke=\"currentColor\"\n        stroke-width=\"1.25\"\n        d=\"M7 17v1a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1v-1a3 3 0 0 0-3-3h-4a3 3 0 0 0-3 3Zm8-9a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z\"\n      ></path>\n    </svg>\n  </span>\n  <input\n    type=\"text\"\n    class=\"input\"\n    placeholder=\"Enter name\"\n    autocomplete=\"off\"\n  />\n</label>\n",
    "css": ".container {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.label {\n  position: relative;\n  display: block;\n  width: 250px;\n  display: flex;\n  border-radius: 6px;\n  border: 2px solid #373737;\n  padding: 15px 8px 15px 10px;\n  text-align: left;\n\n  .icon {\n    position: absolute;\n    top: 53%;\n    right: 0;\n    transform: translate(-50%, -50%);\n    transition: all 0.3s ease;\n    color: #c5c5c5;\n  }\n\n  .input {\n    background-color: transparent;\n    outline: none;\n    border: none;\n    color: #c5c5c5;\n    font-size: 16px;\n  }\n}\n"
