    "html": "<div>\n  <label for=\"inputname\" class=\"block text-gray-800 font-semibold text-sm\"\n    >Input Name</label\n  >\n  <div class=\"mt-2\">\n    <input\n      type=\"text\"\n      name=\"inputname\"\n      class=\"block w-56 rounded-md py-1.5 px-2 ring-1 ring-inset ring-gray-400 focus:text-gray-800\"\n    />\n  </div>\n  <label class=\"pt-1 block text-gray-500 text-sm\">Some Description</label>\n</div>\n",
    "css": ".mt-2{margin-top:0.5rem}.block{display:block}.w-56{width:14rem}.rounded-md{border-radius:0.375rem}.px-2{padding-left:0.5rem;padding-right:0.5rem}.py-1{padding-top:0.25rem;padding-bottom:0.25rem}.py-1\\.5{padding-top:0.375rem;padding-bottom:0.375rem}.pt-1{padding-top:0.25rem}.text-sm{font-size:0.875rem;line-height:1.25rem}.font-semibold{font-weight:600}.text-gray-500{--tw-text-opacity:1;color:rgb(107 114 128 / var(--tw-text-opacity))}.text-gray-800{--tw-text-opacity:1;color:rgb(31 41 55 / var(--tw-text-opacity))}.ring-1{--tw-ring-offset-shadow:var(--tw-ring-inset) 0 0 0 var(--tw-ring-offset-width) var(--tw-ring-offset-color);--tw-ring-shadow:var(--tw-ring-inset) 0 0 0 calc(1px + var(--tw-ring-offset-width)) var(--tw-ring-color);box-shadow:var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow, 0 0 #0000)}.ring-inset{--tw-ring-inset:inset}.ring-gray-400{--tw-ring-opacity:1;--tw-ring-color:rgb(156 163 175 / var(--tw-ring-opacity))}.focus\\:text-gray-800:focus{--tw-text-opacity:1;color:rgb(31 41 55 / var(--tw-text-opacity))}"
