    "html": "<label class=\"toggle\">\n  <input type=\"checkbox\" />\n  <span class=\"track\">\n    <span class=\"thumb\"></span>\n  </span>\n</label>\n",
    "css": ".toggle {\n  display: inline-block;\n  cursor: pointer;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n}\n\n.toggle input {\n  display: none;\n}\n\n.track {\n  position: relative;\n  display: block;\n  width: 41px;\n  height: 22px;\n  background: #080808;\n  border-radius: 15px;\n  transition: background 0.25s;\n}\n\n.thumb {\n  position: absolute;\n  top: 2.5px;\n  left: 2.3px;\n  width: 27px;\n  height: 17px;\n  background: #fff;\n  border-radius: 8px;\n  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);\n  box-shadow:\n    0 1px 2px rgba(0, 0, 0, 0.35),\n    0 6px 12px rgba(0, 0, 0, 0.18);\n}\n\n.toggle input:checked + .track .thumb {\n  transform: translateX(9px);\n}\n"
