    "css": "/* The switch - the box around the slider */\n.switch {\n  font-size: 17px;\n  position: relative;\n  display: inline-block;\n  width: 3.5em;\n  height: 2em;\n}\n\n/* Hide default HTML checkbox */\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n\n/* The slider */\n.slider {\n  --background: #28096b;\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: var(--background);\n  transition: .5s;\n  border-radius: 30px;\n}\n\n.slider:before {\n  position: absolute;\n  content: \"\";\n  height: 1.4em;\n  width: 1.4em;\n  border-radius: 50%;\n  left: 10%;\n  bottom: 15%;\n  box-shadow: inset 8px -4px 0px 0px #fff000;\n  background: var(--background);\n  transition: .5s;\n}\n\ninput:checked + .slider {\n  background-color: #522ba7;\n}\n\ninput:checked + .slider:before {\n  transform: translateX(100%);\n  box-shadow: inset 15px -4px 0px 15px #fff000;\n}"
